<script lang="ts">
  import{onDestroy}from'svelte';import Modal from'./Modal.svelte';import{api}from'../lib/api';import{buildModelTestPayload,pollModelTest,responseText,safeUsageRows,type ModelTestKind}from'../lib/model-test';
  let{model}:{model:string}=$props();let running=$state(false);let menuOpen=$state(false);let modalOpen=$state(false);let kind=$state<ModelTestKind>('text');let taskId=$state('');let result=$state<unknown>(null);let status=$state('');let error=$state('');let controller:AbortController|null=null;let usage=$derived(safeUsageRows(result&&typeof result==='object'?(result as Record<string,unknown>).usage:null));
  async function run(nextKind:ModelTestKind):Promise<void>{if(running)return;kind=nextKind;menuOpen=false;modalOpen=true;running=true;result=null;status='Starting test...';error='';controller=new AbortController();const timeout=window.setTimeout(()=>controller?.abort(),120000);try{const started=await api.post<{task_id:string}>('/admin/api/test',{endpoint:'/v1/responses',payload:buildModelTestPayload(model,nextKind)},controller.signal);taskId=started.task_id;status='Waiting for result...';const completed=await pollModelTest(taskId,controller.signal);taskId='';if(completed.status==='error')throw new Error(completed.error??'Model test failed');if(completed.status==='cancelled')throw new DOMException('Cancelled','AbortError');result=completed.body;status=`Completed with HTTP ${completed.status_code??200}`;}catch(cause){if(taskId){const current=taskId;taskId='';await api.del(`/admin/api/test/${encodeURIComponent(current)}`).catch(()=>undefined);}if(cause instanceof DOMException&&cause.name==='AbortError')status='Test cancelled.';else if(cause instanceof DOMException&&cause.name==='TimeoutError')status='Test timed out.';else error=cause instanceof Error?cause.message:String(cause);}finally{window.clearTimeout(timeout);running=false;controller=null;}}
  async function cancel():Promise<void>{controller?.abort();const current=taskId;taskId='';if(current)await api.del(`/admin/api/test/${encodeURIComponent(current)}`).catch(()=>undefined);}function close():void{if(running)void cancel();modalOpen=false;}onDestroy(()=>{void cancel();});
</script>
<div class="test-group"><button class="btn btn-sm btn-test" disabled={running} onclick={()=>void run('text')}>Test</button><button class="btn btn-sm btn-caret" aria-label={`More tests for ${model}`} onclick={()=>menuOpen=!menuOpen}>▾</button><div class="test-menu" class:open={menuOpen}>{#each [['text','Text'],['stream','Stream'],['tools','Tools'],['vision','Vision'],['reasoning','Reasoning']] as option}<button class="test-menu-item" onclick={()=>void run(option[0] as ModelTestKind)}>{option[1]}</button>{/each}</div></div>
<Modal open={modalOpen} labelledby={`test-title-${model}`} wide onclose={close}><h3 id={`test-title-${model}`}>Test Result — {model}</h3><div class="test-meta"><span class="meta-item"><strong>Type:</strong> {kind}</span>{#if status}<span class="meta-item" role="status"><strong>Status:</strong> {status}</span>{/if}</div>{#if error}<div class="test-output" role="alert">{error}</div>{/if}{#if result!==null}<div class="test-output">{responseText(result)}</div>{/if}{#if usage.length}<div class="test-meta">{#each usage as [label,value]}<span class="meta-item"><strong>{label}:</strong> {value}</span>{/each}</div>{/if}<details class="test-details"><summary>Raw Response</summary><div class="detail-body"><pre>{JSON.stringify(result,null,2)}</pre></div></details><div class="modal-actions">{#if running}<button class="btn btn-danger" onclick={()=>void cancel()}>Cancel</button>{/if}<button class="btn" onclick={close}>Close</button></div></Modal>
